export function collectTwice(fn) { return JSON.stringify(fn("second", fn("first"))); }
export function rows(fn) { return JSON.stringify(fn([{ name: "a", tags: [1, 2] }, { name: "b", tags: [] }])); }
export function record(fn) { return JSON.stringify(fn({ title: "row", values: [3, 4], surplus: true })); }
